(function(){
'use strict';
const D=globalThis.RA.D;
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+q.s,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('post','Several histories meet in post: the mail/job senses came through French/Italian posta for a station or appointed place; post “after” is from Latin post; the upright pole sense has a separate history.',[C('post.s1','mail','A thick bundle of post arrived at the office after the holiday weekend.','假日周末过后，办公室收到了一大摞邮件。','bundle of post','uncountable noun','In British English post can mean letters and parcels collectively.'),C('post.s2','employment','After years in the field, she accepted a post as director of the clinic.','在基层工作多年后，她接受了诊所主任一职。','accepted a post','count noun','A post is a job, especially an appointed position.'),C('post.s4','communication','Please post the signed form online before Friday.','请在周五前把签署好的表格发布到网上。','post the form online','imperative verb','The verb means publish online as well as send by mail.')],M('She accepted a post as director by refusing the appointed job.','She accepted a post as director of the clinic.','A post can be an appointed job; accepting one means taking it.','meaning'),[Q(1,'What arrived at the office?','letters and parcels','a new director','a metal pole','Post can mean mail collectively.'),Q(2,'What did she accept?','an appointed job','a parcel','a wooden stake','A post can be a position or job.'),Q(4,'Where should the form be published?','online','inside a mailbox only','on a fence as a pole','Post as a verb can mean publish online.'),Q(1,'In British usage, a bundle of post is a bundle of what?','mail','staff positions','fence posts','The mail sense covers letters and parcels.')]);
P('post-mortem','From Latin post “after” + mortem, accusative of mors “death”; the adverbial phrase means after death.',C('post-mortem.s1','medicine','The report noted that the symptoms had appeared post-mortem, after the patient had died.','报告指出，这些症状是在患者去世后出现的。','appeared post-mortem','adverbial modifier','The source entry treats this hyphenated form as an adverb meaning after death.'),M('The post-mortem symptoms appeared several days before the patient was born.','The post-mortem symptoms appeared after the patient had died.','Post-mortem means after death, not before birth.','meaning'),[Q(1,'When did the symptoms appear?','after death','before birth','during childhood only','Post-mortem means occurring after someone has died.'),Q(1,'Which event is post-mortem?','a finding recorded after death','a symptom before birth','a routine check during life','The adverb refers to the period after death.'),Q(1,'What does mortem refer to in the phrase?','death','mail','a job','Latin mortem means death.'),Q(1,'Choose the closest paraphrase of post-mortem.','after the person died','before the person was born','after a postal delivery','The word combines post “after” with death.')]);
P('postage','From post + -age, naming the charge associated with sending mail.',C('postage.s1','mail','The parcel was returned because the postage did not cover its weight.','包裹因邮资不足以支付其重量对应的费用而被退回。','postage did not cover its weight','subject + verb','Postage is the money charged for sending a letter or parcel.'),M('The parcel needed more postage because the mail fee had already been paid twice.','The parcel needed more postage because the fee paid was too low.','Insufficient postage means the mailing charge paid did not cover the parcel.','meaning'),[Q(1,'Why was the parcel returned?','the postage was insufficient','its address was a postcard','it was too light to mail','Postage is the fee for sending mail.'),Q(1,'What does postage pay for?','sending a letter or parcel','printing a photograph','renting a mailbox as a home','Postage is the mailing charge.'),Q(2,'What did postage refer to in the seller’s bill?','the total cost of mailing the goods','the price of the goods alone','the parcel’s weight','The second sense is the total mailing cost.'),Q(1,'If postage is short, what is missing?','enough mailing fee','a stamp-shaped address','a parcel’s contents','The fee must cover the cost of sending it.')]);
P('postal','From French postal, formed from poste, ultimately from Italian posta “station”; the adjective relates to the mail system.',C('postal.s1','mail','A postal worker sorted the parcels by destination before the truck left.','邮政工作人员在卡车出发前按目的地分拣包裹。','postal worker','adjective + noun','Postal means connected with sending letters and parcels.'),M('The postal worker sorted parcels by their musical keys.','The postal worker sorted parcels by their destinations.','Postal describes mail services; sorting parcels by destination fits that work.','meaning'),[Q(1,'What does postal describe?','the system for sending mail','a musical instrument','a cooking pot','Postal relates to the official mail system.'),Q(1,'What did the postal worker sort?','parcels by destination','pollen by color','chairs by comfort','The example describes mail handling.'),Q(1,'Which is a postal service?','delivering a letter','repairing a bridge','growing a potato','Postal concerns sending and delivering mail.'),Q(1,'Which phrase uses postal correctly?','postal address','postal feather','postal poem','An address can be part of the mail system.')]);
P('postcard','A compound of post + card, named for a card sent through the mail; the first official postal cards appeared in the 19th century.',[C('postcard.s1','correspondence','I sent my cousin a postcard from the coast with a short note on the back.','我从海边给表亲寄了一张明信片，并在背面写了简短留言。','sent a postcard','verb + object','A postcard is a card for a brief message sent through the mail.'),C('postcard.s2','travel','The postcard showed the old harbor at sunset.','这张风景明信片展示了日落时的古老港口。','postcard showed','subject + verb','A scenic postcard features an image of a place.')],M('He sent a postcard by sealing it inside a large private envelope.','He sent a postcard with its address written on the card itself.','A postcard is normally mailed as a card, not enclosed in an envelope.','meaning'),[Q(1,'Where did she write the short note?','on the back of the card','inside a parcel','on the postage machine','A postcard carries a short message.'),Q(2,'What image did the scenic postcard show?','the old harbor at sunset','a blank sheet','a medical scan','The scenic sense is a card showing a place.'),Q(1,'Which item can be mailed as a postcard?','a picture card with a brief message','a pot of soup','an unaddressed telephone call','A postcard is a card sent through the mail.'),Q(2,'What makes this postcard scenic?','its picture shows a location','it has no picture or message','it is a postal fee','A scenic postcard displays a place.')]);
P('postcode','A compound of post + code, a code added to an address to help sort mail; “postcode” is especially British.',C('postcode.s1','mail','Adding the postcode helped the sorting machine route the letter to the right district.','加上邮编后，分拣机便能把信件送往正确的区域。','adding the postcode','gerund subject','A postcode is a locality code used in mail sorting.'),M('The postcode sent the letter to the wrong country because it identified the correct district.','The postcode helped route the letter to the correct district.','A postcode identifies a delivery area and helps mail reach it.','meaning'),[Q(1,'What did the postcode help the machine do?','route the letter to a district','weigh the envelope','write the message','A postcode sorts mail by locality.'),Q(1,'What is a postcode?','a code in a mailing address','a kind of postcard picture','a fee paid at the counter','It is a code used to sort mail.'),Q(1,'Where is postcode especially common?','British English','only in ancient Greek','in medical Latin','Postcode is the usual British term.'),Q(1,'What can a postcode identify?','a delivery locality','the letter’s author’s age','the stamp’s color','It helps identify the destination area.')]);
P('postdate','Post- “after” + date; the verb can put a later date on a document or describe something occurring later.',[C('postdate.s1','documents','The clerk postdated the check to the first day of next month.','职员把支票日期填成了下个月的第一天。','postdated the check','verb + object','The verb means write a date later than the actual date.'),C('postdate.s2','chronology','The earliest surviving copy may postdate the original by several decades.','现存最早的抄本可能比原作晚几十年。','may postdate the original','modal + verb + object','The temporal sense means occur later than another thing.')],M('The clerk postdated the check to a date three months before it was written.','The clerk postdated the check to a later date.','To postdate a document is to give it a later date, not an earlier one.','meaning'),[Q(1,'What date did the clerk write on the check?','a later date','a date before it was written','no date at all','Postdate can mean write a date later than the actual one.'),Q(2,'How might the copy relate to the original?','it may be from a later time','it must be older','it is the same physical object','To postdate something is to come after it.'),Q(1,'Which action postdates a contract?','writing a future date on it','writing yesterday’s date on it','signing it without a date','The verb means give a document a later date.'),Q(2,'If A postdates B, which happened later?','A','B','neither; the word means simultaneous','Postdate means occur after another event.')]);
P('poster','From post + -er, because printed bills were posted on walls or poles; the word names a large printed display.',C('poster.s1','advertising','A bright poster outside the theater advertised the new comedy.','剧院外一张鲜艳的海报为新喜剧做广告。','poster outside the theater','noun + prepositional phrase','A poster is a large printed picture used for display or advertising.'),M('The theater advertised the show with a poster small enough to fit inside a postage stamp.','The theater advertised the show with a large printed poster.','A poster is generally a large display sheet, not a stamp-sized mark.','meaning'),[Q(1,'What did the poster advertise?','a new comedy','a postal fee','a medical treatment','Posters commonly display advertisements.'),Q(1,'Where was it displayed?','outside the theater','inside a sealed parcel','under the stage floor','A poster is put up for people to see.'),Q(2,'Which item is a public-information poster?','a large sheet announcing road closures','a private text message','a small coin','The second source sense is a large notice for the public.'),Q(1,'What is a poster?','a large printed display','a type of mailbox','a list of postage costs','The source sense is a large printed picture or notice.')]);
P('posterity','From Latin posteritas “future generations,” from posterus “coming after.”',C('posterity.s1','history','The historian hoped that posterity would preserve the letters and learn from them.','历史学家希望后世保存这些信件并从中吸取教训。','posterity would preserve','subject + modal','Posterity means people in generations to come.'),M('The historian wrote for posterity, meaning people who had lived centuries before him.','The historian wrote for posterity, meaning people who would live in later generations.','Posterity refers to future generations, not people of the past.','meaning'),[Q(1,'Who is posterity?','people in future generations','the historian’s ancestors only','people living in another country today','Posterity means all generations that come later.'),Q(1,'What did the historian hope posterity would do?','preserve and learn from the letters','erase the letters','write them before he did','The example describes what later generations might do.'),Q(1,'Which phrase is closest to posterity?','future generations','the current committee','the original author','Posterity consists of people who come later.'),Q(1,'Why might someone care about posterity?','they hope later people remember their work','they wish to mail a parcel','they want to change a postcode','The word concerns generations in the future.')]);
P('postgraduate','Post- “after” + graduate, referring to study after completion of an initial university degree.',C('postgraduate.s1','education','As a postgraduate, Lena is researching how coastal towns adapt to rising seas.','作为研究生，莉娜正在研究沿海城镇如何适应海平面上升。','as a postgraduate','as-phrase','Postgraduate can be a student or describe study after a first degree.'),M('He enrolled as a postgraduate before completing any first degree.','He enrolled as a postgraduate after completing his first degree.','Postgraduate study follows an initial degree.','meaning'),[Q(1,'What is Lena doing as a postgraduate?','researching after an initial degree','starting primary school','mailing a postcard','A postgraduate studies beyond a first degree.'),Q(1,'Which student is a postgraduate?','someone studying for a further degree','someone who has not begun university','someone delivering mail','The noun refers to a student continuing after a first degree.'),Q(1,'What does post- mean in postgraduate?','after','before','under','The prefix post- means after.'),Q(1,'Which phrase is postgraduate study?','a master’s program after a bachelor’s degree','a first reading lesson','a weekend hobby only','Postgraduate education comes after an initial degree.')]);
P('posthumous','From Latin postumus “last-born, last,” later used for something appearing after a person’s death; its history is not simply post + humus.',C('posthumous.s1','publishing','The author’s posthumous novel was published a year after she died.','作者去世一年后，她的遗作小说才得以出版。','posthumous novel','adjective before noun','Posthumous describes work or recognition appearing after death.'),M('The author’s posthumous novel was published while she was alive and still writing it.','The author’s posthumous novel was published after she died.','Posthumous means occurring or published after the person’s death.','meaning'),[Q(1,'When was the novel published?','after the author died','before she was born','while she was still writing it','Posthumous work appears after its creator’s death.'),Q(1,'Which award might be posthumous?','one given after the recipient dies','one given before a contest starts','one given during childhood','The adjective means after death.'),Q(1,'What does posthumous modify in the example?','novel','year','author','It describes the novel’s publication after the author died.'),Q(1,'Choose the closest meaning of posthumous.','published after death','published anonymously','published before completion','The term refers to events or works following death.')]);
P('posthumously','From posthumous + adverb suffix -ly; it means after the person concerned has died.',C('posthumously.s1','awards','The composer was posthumously awarded a medal for the music she wrote decades earlier.','这位作曲家因数十年前创作的音乐而在身后获颁奖章。','was posthumously awarded','adverb modifying passive verb','The adverb says the award came after the recipient’s death.'),M('The composer was posthumously awarded the medal while she was alive to accept it.','The composer was posthumously awarded the medal after her death.','Posthumously means the award was made after she died.','meaning'),[Q(1,'When did the composer receive the medal?','after her death','before she wrote any music','during the award ceremony while alive','The adverb means after the person has died.'),Q(1,'Which event can happen posthumously?','a book is published after its author’s death','a person writes a letter tomorrow','a student attends class today','Posthumously marks something occurring after death.'),Q(1,'Which verb does posthumously modify?','was awarded','composer','decades','The adverb modifies the awarding.'),Q(1,'What does posthumously mean?','after the person died','before a person is born','without a name','It means occurring after death.')]);
P('postman','A compound of post + man, a traditional British term for a male letter and parcel deliverer; “postal worker” is gender-neutral.',C('postman.s1','mail','The postman left the parcel with the neighbor when nobody answered the door.','无人应门时，邮递员把包裹留给了邻居。','postman left the parcel','noun subject','A postman delivers mail; the word traditionally specifies a man.'),M('The postman delivered the parcel by leaving it at the sorting depot instead of the address.','The postman delivered the parcel to the address or an agreed neighbor.','Delivery means bringing mail to its destination, not leaving it at the depot.','meaning'),[Q(1,'What did the postman deliver?','a parcel','a university degree','a pottery wheel','A postman delivers letters and parcels.'),Q(1,'Where did he leave it?','with the neighbor','inside the postbox at the depot','in the theater','The sentence says the neighbor accepted it.'),Q(1,'What job does postman name?','a male mail deliverer','a post office manager','a person who prints posters','The source sense is a man who delivers mail.'),Q(1,'What is a gender-neutral alternative?','postal worker','posthumous author','postcode','Postal worker does not specify gender.')]);
P('postmaster','A compound of post + master, naming the person in charge of a post office.',C('postmaster.s1','mail service','The postmaster arranged extra staff before the holiday rush.','节日寄件高峰前，邮局主管安排了额外人手。','postmaster arranged','noun subject','A postmaster manages a post office.'),M('The postmaster managed the post office by refusing to supervise its staff or services.','The postmaster managed the post office and organized its staff.','A postmaster is responsible for managing the post office.','meaning'),[Q(1,'What did the postmaster arrange?','extra staff','a posthumous novel','a potato crop','A postmaster manages a post office.'),Q(1,'When were extra staff needed?','before the holiday rush','after the office closed forever','during a medieval battle','The sentence mentions the seasonal mailing rush.'),Q(1,'Who is a postmaster?','a manager of a post office','a person who writes postcards','a parcel itself','The source sense identifies the manager.'),Q(1,'Which responsibility fits a postmaster?','overseeing postal operations','grading a university thesis','making a pottery bowl','The role is to manage a post office.')]);
P('postmodern','Post- + modern; the adjective labels art, architecture, and thought that question modernist certainty and mix styles.',C('postmodern.s1','architecture','The postmodern library paired a classical facade with a bright, asymmetrical glass wing.','这座后现代图书馆把古典立面与明亮、不对称的玻璃侧翼结合起来。','postmodern library','adjective before noun','The example uses mixed styles, characteristic of the source sense.'),M('The building was called postmodern because it followed one strict classical style without irony or variation.','The building was called postmodern because it mixed classical and contemporary styles.','Postmodern work often mixes styles and questions a single dominant style.','meaning'),[Q(1,'What feature makes the library postmodern?','it combines contrasting styles','it copies one style exactly','it has no facade','The sense describes mixed styles and challenges to certainty.'),Q(1,'Which design could be postmodern?','a historic facade beside an unexpected glass wing','a perfect copy of one ancient temple','a plain unbuilt idea','Postmodern design often juxtaposes styles.'),Q(1,'What does postmodern modify?','library','facade','glass','The adjective describes the building.'),Q(1,'Which idea is associated with postmodernism?','questioning a single universal explanation','insisting one style is always correct','avoiding all artistic choices','The source sense questions modernist certainty.')]);
P('postmodernism','From postmodern + -ism, naming a broad cultural movement that mixes styles and questions universal explanations.',C('postmodernism.s1','culture','The seminar traced postmodernism through novels that mixed genres and challenged a single authoritative narrator.','研讨课通过混合体裁、质疑单一权威叙述者的小说追溯后现代主义。','traced postmodernism','verb + object','Postmodernism is a cultural movement skeptical of universal narratives.'),M('The seminar defined postmodernism as strict loyalty to one universal narrative and one fixed style.','The seminar described postmodernism as mixing styles and questioning universal narratives.','Postmodernism is associated with stylistic mixture and skepticism about universal explanations.','meaning'),[Q(1,'What did the novels mix?','genres','postage stamps','chemical elements','The example links postmodernism with mixing genres.'),Q(1,'What kind of narrator did they challenge?','a single authoritative narrator','every narrator equally','no narrator at all','The sentence describes a challenge to single authority.'),Q(1,'What does -ism form in postmodernism?','a noun naming a movement or doctrine','a past-tense verb','a plural adjective','The suffix names a broad cultural movement.'),Q(1,'Which attitude fits postmodernism in this entry?','skepticism toward universal explanations','certainty that one story explains everything','rejection of all styles','The source sense emphasizes doubt about universal explanations.')]);
P('postmortem','From Latin post mortem, “after death”; as a noun it can mean an autopsy or a review after an event.',[C('postmortem.s1','project review','After the failed launch, the team held a postmortem to identify what went wrong.','发布失败后，团队举行复盘，查找问题所在。','held a postmortem','verb + object','The figurative noun is a review conducted after an event.'),C('postmortem.s2','medicine','The coroner ordered a postmortem to determine the cause of death.','验尸官下令进行尸体解剖，以确定死因。','ordered a postmortem','verb + object','The medical noun refers to an examination of a body after death.')],M('The launch postmortem happened before the launch so the team could review its outcome.','The launch postmortem happened afterward so the team could review its outcome.','A postmortem review follows the event it examines.','meaning'),[Q(2,'Why did the team hold a postmortem?','to review what went wrong after launch','to plan the launch before it happened','to examine a living patient','A figurative postmortem reviews an event after it ends.'),Q(1,'What did the coroner order?','an examination after death','a postal delivery','a postgraduate degree','The medical sense is an autopsy.'),Q(2,'Which timing fits a project postmortem?','after the project is complete','before work begins','during every meeting','A postmortem is retrospective.'),Q(1,'What can postmortem mean medically?','an autopsy','a future appointment','a mail code','The medical noun is an examination of a body after death.')]);
P('postoperative','Post- + operative, from Latin operari “to work”; postoperative refers to the period following surgery.',C('postoperative.s1','medicine','During the postoperative visit, the surgeon checked the incision and reviewed the recovery plan.','术后复诊时，外科医生检查了切口并讨论康复计划。','postoperative visit','adjective before noun','The adjective relates to the time after an operation.'),M('The postoperative visit took place before the surgeon performed the operation.','The postoperative visit took place after the operation.','Postoperative means following surgery.','meaning'),[Q(1,'When did the visit occur?','after surgery','before the operation','during a postal delivery','Postoperative means relating to the period after surgery.'),Q(1,'What did the surgeon check?','the incision','the postcode','the theater poster','The context concerns surgical recovery.'),Q(1,'Which care is postoperative?','monitoring recovery after an operation','preparing for a first lecture','sorting mail','The adjective refers to after surgery.'),Q(1,'What does post- mean in postoperative?','after','under','against','The prefix post- means after.')]);
P('postpone','From Latin postponere “put after,” formed from post “after” + ponere “put.”',[C('postpone.s1','scheduling','Because of heavy snow, the school postponed the outdoor concert until Friday.','由于大雪，学校把户外音乐会推迟到周五。','postponed the concert','verb + object','This sense moves a planned event to a later time.'),C('postpone.s2','decisions','The board postponed a decision until it had reviewed the safety report.','董事会暂缓作出决定，直到审阅完安全报告。','postponed a decision','verb + object','The verb can delay an action until circumstances are suitable.')],M('They postponed the concert by holding it earlier than the scheduled date.','They postponed the concert by moving it to a later date.','To postpone means delay until later, not advance.','meaning'),[Q(1,'Why was the concert postponed?','heavy snow','a completed rehearsal','a new poster','The sentence gives snow as the reason for delay.'),Q(2,'What did the board wait for before deciding?','a safety report review','a postcard delivery','a pottery lesson','Postpone can mean defer a decision.'),Q(1,'What happens when an event is postponed?','it is moved to a later time','it is cancelled forever by definition','it happens earlier','Postpone means delay, not necessarily cancel.'),Q(2,'Which action postpones a decision?','waiting for needed information','voting immediately','ignoring the report and pretending to decide','The second sense is to defer action until the time is right.')]);
P('postscript','From Latin post scriptum “written after,” the phrase used for a note added after a letter’s signature.',C('postscript.s1','correspondence','She added a postscript beneath her signature to mention the enclosed photograph.','她在签名下方补写附言，提到随信附上的照片。','added a postscript','verb + object','A postscript is an additional note after the main letter and signature.'),M('She wrote the postscript before the greeting at the start of the letter.','She wrote the postscript after her signature at the end of the letter.','A postscript comes after the main text, usually after the signature.','meaning'),[Q(1,'Where did she put the postscript?','beneath her signature','before the greeting','on the outside of the stamp','A postscript is added after a letter’s signature.'),Q(1,'What did the postscript mention?','an enclosed photograph','the postal code only','the paper’s weight','The example specifies the extra note’s content.'),Q(1,'What does P.S. usually introduce?','a postscript','the letter’s address','the postmaster','P.S. marks a note written after the main letter.'),Q(1,'What does postscript literally mean?','written after','written by hand only','written on a postcard','It comes from Latin post scriptum, “written after.”')]);
P('postulate','From Latin postulare “to demand or request”; in logic and mathematics, a postulate is an assumption accepted as a starting point.',[C('postulate.s1','reasoning','The model postulates that air resistance is negligible before calculating the falling object’s speed.','计算物体下落速度前，模型先假定空气阻力可以忽略。','postulates that air resistance is negligible','verb + that-clause','The verb introduces an assumption used as a basis for reasoning.'),C('postulate.s2','mathematics','The proof begins with the postulate that two parallel lines never meet.','证明从“两条平行线永不相交”这一公设开始。','with the postulate that','noun + that-clause','A postulate is a proposition accepted without proof as a starting point.')],M('The proof postulates that two parallel lines meet at exactly one point.','The proof postulates that two parallel lines do not meet.','The example’s assumed property of parallel lines is that they never meet.','meaning'),[Q(1,'What does the model assume?','air resistance is negligible','the object has no mass','gravity points upward','To postulate is to assume something as a premise.'),Q(2,'What is the postulate in the proof?','parallel lines do not meet','all lines are circles','a triangle has no sides','A postulate is a starting proposition accepted without proof.'),Q(1,'Which phrase introduces a postulate?','The theory postulates that…','The parcel postages…','The artist potters…','Postulate can take a that-clause stating an assumption.'),Q(2,'How is a postulate used?','as a basis for reasoning','as a postage fee','as a final experimental result','A postulate is an accepted starting point.')]);
P('posture','From French posture and Latin positura “position,” from ponere “to place.”',C('posture.s1','health','The physiotherapist corrected his posture by asking him to sit upright and relax his shoulders.','理疗师让他坐直并放松肩膀，以纠正他的姿势。','corrected his posture','verb + object','Posture is the way a person holds their body.'),M('She improved her posture by slouching lower over the desk.','She improved her posture by sitting upright.','Good posture involves holding the body upright and aligned.','meaning'),[Q(1,'What did the physiotherapist correct?','the way he held his body','his postal code','his cooking pot','Posture means the position in which someone holds their body.'),Q(1,'Which behavior improves posture in this example?','sitting upright','slouching over the desk','twisting the shoulders sharply','The sentence says he sat upright and relaxed his shoulders.'),Q(1,'What does posture refer to?','body position','a mail delivery','a unit of weight','The source sense is how the body is held.'),Q(1,'Which sentence uses posture correctly?','The dancer maintained a balanced posture.','The dancer mailed a posture.','The dancer measured one posture of flour.','Posture describes body position.')]);
P('postwar','A transparent compound of post- “after” and war; it describes the period following a war.',C('postwar.s1','history','Postwar housing programs helped families rebuild homes destroyed during the conflict.','战后住房计划帮助家庭重建在冲突中被毁的家园。','postwar housing programs','adjective before noun','Postwar means belonging to the period after a war.'),M('The postwar plan was carried out before the war had begun.','The postwar plan was carried out after the war ended.','Postwar refers to the period following a war.','meaning'),[Q(1,'When did the housing programs operate?','after the conflict','before the war began','during a mail delivery','Postwar means belonging to the period after a war.'),Q(1,'What does post- mean in postwar?','after','between','against','The prefix post- means after.'),Q(1,'Which event is postwar?','rebuilding after fighting ends','mobilizing before the first battle','planning a postcard','The adjective describes the period after war.'),Q(1,'What were families rebuilding?','homes damaged in the conflict','their postage fees','a pot of soup','The example states that their homes had been destroyed.')]);
P('pot','From Old English pott, probably borrowed from a Germanic or Latin source; its deeper origin is uncertain.',[C('pot.s1','cooking','She simmered the lentils in a heavy pot while the bread baked.','面包烘烤时，她用厚锅炖扁豆。','in a heavy pot','prepositional phrase','A pot is a deep round cooking or storage container.'),C('pot.s2','gardening','The basil grew in a clay pot beside the sunny kitchen window.','罗勒种在厨房窗边的陶盆里。','in a clay pot','prepositional phrase','A pot can be a container for growing a plant.'),C('pot.s3','gardening','We potted the young lemon tree in a larger container before winter.','入冬前，我们把柠檬幼树移栽到更大的盆里。','potted the young lemon tree','verb + object','As a verb, pot means put a plant into a pot.')],M('She cooked the lentils in a pot by planting them in the container.','She cooked the lentils in a pot on the stove.','A pot is the cooking container; planting is not the cooking action.','meaning'),[Q(1,'Where did she simmer the lentils?','in a cooking container','in a postal envelope','in a flower bed','Pot can name a deep round cooking vessel.'),Q(2,'What held the basil?','a clay container for growing plants','a saucepan on the stove','a mailbag','A plant pot is a container in which a plant grows.'),Q(3,'What does “potted the lemon tree” mean?','put it into a pot','cooked it for dinner','mailed it to a customer','The verb means place a plant in a container.'),Q(1,'Which object is a pot?','a deep round vessel for cooking soup','a thin postcard','a metal measuring pole','The source sense is a cooking or storage container.')]);
P('potash','From pot + ash, a name reflecting the historical method of leaching alkaline salts from wood ashes in pots.',C('potash.s1','chemistry','The farmer added potash to the soil to supply potassium compounds for the crop.','农民向土壤施钾碱，为作物补充钾化合物。','added potash to the soil','verb + object','Potash is an alkaline potassium compound and is used in agriculture.'),M('The farmer added potash to remove every potassium nutrient from the soil.','The farmer added potash as a source of potassium for the crop.','Potash is a potassium compound used as a nutrient source, not to remove potassium.','meaning'),[Q(1,'Why did the farmer use potash?','to supply potassium compounds','to remove all nutrients','to mail a soil sample','Potash contains potassium compounds and is used in agriculture.'),Q(1,'What does the name potash recall?','salts obtained from ashes in pots','a potato dish','a postal station','It is traditionally explained through pot ashes.'),Q(1,'Which field uses potash as fertilizer?','agriculture','poetry','postal sorting','Potash is used in farming.'),Q(1,'What kind of compound is potash?','an alkaline potassium compound','a pure noble gas','a type of animal protein','The source sense identifies potassium compounds.')]);
P('potassium','Named from potash + chemical -ium; the element was isolated by Humphry Davy in 1807.',C('potassium.s1','chemistry','Potassium reacts vigorously with water, so the metal is stored under oil in the laboratory.','钾与水反应剧烈，因此实验室把这种金属存放在油中。','reacts vigorously with water','verb + prepositional phrase','Potassium is element 19, a reactive silvery metal.'),M('The laboratory stored potassium in an open jar of water because the metal is inert.','The laboratory stored potassium under oil because it reacts vigorously with water.','Potassium is highly reactive with water and is stored away from it.','meaning'),[Q(1,'What is potassium?','a reactive chemical element','a plant pot','a postal code','Potassium is element 19.'),Q(1,'Why was the metal stored under oil?','it reacts vigorously with water','it dissolves into harmless sugar','it is a gas at room temperature','Oil keeps reactive potassium away from water and air.'),Q(1,'Which symbol represents potassium?','K','P','Po','Its chemical symbol is K.'),Q(1,'What appearance does the source describe?','silvery metal','clear liquid gas','blue ceramic','Potassium is a silvery metal.')]);
P('potato','From Spanish patata, borrowed through Caribbean languages; the word may reflect blending with papa, an Andean name for the potato.',C('potato.s1','food','He scrubbed each potato before baking it with the skin on.','他把每个土豆都刷洗干净，然后连皮烤制。','scrubbed each potato','count noun object','This sense names the edible tuber; potato can also mean the food prepared from it.'),M('She peeled the potato by leaving its skin untouched and removing its inner flesh.','She peeled the potato by removing its skin.','Peeling removes the outside skin, not the inside flesh.','meaning'),[Q(1,'What did he scrub?','a round edible tuber','a postal card','a clay vessel','Potato names the vegetable.'),Q(2,'What does “potato” mean in “mashed potato”?','the vegetable prepared as food','a plant pot','a unit of weight','The food sense refers to the vegetable when cooked.'),Q(1,'How did he prepare the potato?','baked it with the skin on','mailed it as a postcard','planted it in a letter','The example says it was baked unpeeled.'),Q(1,'Which plant part is commonly eaten as a potato?','an underground tuber','a flower petal','a seed pod','Potatoes are tubers eaten as food.')]);
P('potency','From Latin potentia “power, ability,” from potens “powerful.”',C('potency.s1','medicine','The medicine’s potency was tested at several doses to measure how strongly it affected the infection.','研究人员用多个剂量测试药物效力，测量它对感染的作用强度。','medicine’s potency','possessive noun subject','Potency is the capacity to produce a strong effect.'),M('The medicine had high potency because it produced no effect at any dose.','The medicine had high potency because a small dose produced a strong effect.','Potency is the power to produce an effect; no effect indicates low potency.','meaning'),[Q(1,'What did researchers measure?','how strongly the medicine worked','the color of the medicine bottle','the postage cost','Potency is the capacity to produce a strong result.'),Q(1,'What would high potency suggest?','a strong effect at a small dose','no effect at any dose','a large bottle only','A potent substance can have a strong effect.'),Q(1,'Which word is closest to potency?','strength','weakness','container','Potency refers to power or effectiveness.'),Q(1,'Why test several doses?','to assess the medicine’s effect strength','to measure the patient’s postcode','to compare ceramic pots','Different doses help evaluate potency.')]);
P('potent','From Latin potentem, accusative of potens “powerful, able.”',[C('potent.s1','medicine','The doctor warned that even a small amount of the potent drug could cause severe side effects.','医生提醒，即使少量这种强效药也可能引起严重副作用。','potent drug','adjective before noun','This sense means having a strong physical effect.'),C('potent.s2','rhetoric','Her brief testimony was a potent argument for changing the unsafe policy.','她简短的证词有力地支持了修改不安全政策。','potent argument','adjective before noun','The figurative sense describes something with strong influence or persuasive force.')],M('The potent medicine had no effect even at the highest dose.','The potent medicine had a strong effect even at a low dose.','Potent means having a strong effect.','meaning'),[Q(1,'Why did the doctor urge caution?','the drug could have strong effects','the medicine was only a flavoring','the policy was already safe','Potent describes a substance with a strong bodily effect.'),Q(2,'What made the testimony potent?','it strongly supported policy change','it was delivered after the policy changed','it contained no argument','The figurative sense means influential or forceful.'),Q(1,'Which substance is potent?','one effective in a very small amount','one that never acts','one that is only a container','Potent means having a strong effect.'),Q(2,'What is a potent argument?','a persuasive argument','a heavy cooking pot','a weak rumor','The adjective can describe powerful reasoning.')]);
P('potential','From Medieval Latin potentialis, from potentia “power, possibility,” based on potens “able.”',[C('potential.s1','planning','The empty lot is a potential site for a new clinic, although funding is not settled.','这块空地可能成为新诊所选址，不过资金尚未落实。','potential site','adjective before noun','As an adjective it means possible or likely, not yet actual.'),C('potential.s2','ability','The young violinist has the potential to lead an orchestra one day.','这位年轻小提琴手有潜力将来担任乐团首席。','has the potential','noun + infinitive','As a noun it means an ability that may develop.'),C('potential.s3','possibility','There is potential for flooding if the river rises overnight.','如果河水夜间上涨，就有发生洪水的可能。','potential for flooding','noun + for','The noun can also mean the possibility that something will happen.')],M('The lot is a potential clinic site, so the clinic is already built and operating there.','The lot is a potential clinic site, but the clinic has not yet been built.','Potential means possible in the future, not already realized.','meaning'),[Q(1,'What does potential mean before “site”?','possible but not yet actual','already operating','impossible under any condition','The adjective describes a possible future site.'),Q(2,'What does the violinist have?','an ability that may develop','a completed orchestra','a postal job','Potential as a noun can mean a capacity to develop.'),Q(3,'What is there potential for?','flooding','pottery','postage','The phrase names a possible event.'),Q(1,'Which is a potential solution?','a possible answer still under review','a result already impossible','a completed mistake','Potential describes future possibility.')]);
P('potentiality','From potential + -ity, from Latin potentialis; it names an unrealized quality or capacity that may develop.',C('potentiality.s1','philosophy','The architect saw the potentiality of the narrow courtyard as a quiet reading garden.','建筑师看到了这处狭窄庭院发展成安静阅读花园的潜力。','potentiality of the courtyard','of-phrase','Potentiality is a quality or ability that could be realized later.'),M('The courtyard’s potentiality was its completed state that could never change.','The courtyard’s potentiality was its capacity to become a reading garden.','Potentiality refers to a possibility not yet realized.','meaning'),[Q(1,'What did the architect see in the courtyard?','a capacity to become a garden','a finished garden already there','no possible future use','Potentiality is an unrealized possibility.'),Q(1,'Which noun is closest to potentiality?','capacity','completion','impossibility','Potentiality names an ability or quality that may develop.'),Q(1,'Has the courtyard already become a reading garden?','No, it may develop into one.','Yes, the example says it is complete.','It has been demolished.','The sense is a possible future development.'),Q(1,'What does -ity form in potentiality?','a noun naming a quality or state','a past-tense verb','a comparative adjective','The suffix forms an abstract noun.')]);
P('potentially','From potential + adverb suffix -ly; it means possibly, if circumstances develop in a certain way.',C('potentially.s1','risk assessment','The shortcut is potentially dangerous when the road is icy.','道路结冰时，这条近路可能很危险。','potentially dangerous','adverb modifying adjective','Potentially signals a possibility rather than a certainty.'),M('The route is potentially dangerous, so danger is absolutely certain in every condition.','The route is potentially dangerous if ice forms.','Potentially means possible under conditions, not certain in all cases.','meaning'),[Q(1,'What does potentially dangerous mean?','it may be dangerous in some conditions','it is always harmless','it is certainly dangerous every time','Potentially marks possibility, not certainty.'),Q(1,'When does the shortcut become risky?','when the road is icy','when the road is dry','only after it is closed','The context states the condition.'),Q(1,'Which word does potentially modify?','dangerous','shortcut','road','The adverb modifies the adjective.'),Q(1,'Choose a close paraphrase of potentially.','possibly','definitely','never','Potentially means possibly.')]);
P('potion','From Old French potion and Latin potionem “a drink,” from potare “to drink.”',C('potion.s1','literature','The healer offered the traveler a bitter potion said to ease the fever.','治疗者递给旅人一剂苦药水，据说能缓解发烧。','a bitter potion','adjective before noun','A potion is a liquid intended to be drunk as medicine or as a magical mixture in stories.'),M('The healer gave the traveler a potion by asking him to swallow a dry wooden spoon.','The healer gave the traveler a potion, a liquid medicine to drink.','A potion is a drinkable liquid, not a dry utensil.','meaning'),[Q(1,'What did the healer offer?','a liquid medicine','a postal code','a clay pot','Potion names a liquid meant to be drunk.'),Q(1,'What was the potion said to do?','ease the fever','deliver the parcel','shape the pot','The sentence says it was intended to help with fever.'),Q(1,'Which fictional item is a potion?','a magic liquid someone drinks','a metal power unit','a postcard image','Stories often use potion for a magical drink.'),Q(1,'What does the word’s Latin source relate to?','drinking','writing','planting','Potion comes from a Latin word for a drink.')]);
P('potted','From pot + -ed, describing plants grown in containers or food preserved in pots.',C('potted.s1','gardening','The potted fern sat on a shelf where it received indirect sunlight.','这盆蕨类植物放在能照到散射光的架子上。','potted fern','adjective before noun','Potted can describe a plant grown in a pot or food packed in one.'),M('The potted fern grew directly in the open field with no container.','The potted fern grew in a container on the shelf.','A potted plant is grown in a pot.','meaning'),[Q(1,'Where was the fern grown?','in a container','in a river','inside a postcard','Potted describes a plant grown in a pot.'),Q(1,'What kind of light did it receive?','indirect sunlight','complete darkness','light from a postage stamp','The sentence says the shelf received indirect sunlight.'),Q(1,'Which food can be potted?','a preserved meat packed in a pot','a fresh fern','a postal receipt','Potted also describes food packed in a pot.'),Q(1,'What does -ed contribute in potted?','a state or condition of being in a pot','a future action','a plural count','Potted describes the plant’s container-grown state.')]);
P('potter','From pot + agent suffix -er; it names a craft worker who shapes and fires clay vessels.',C('potter.s1','craft','The potter centered the wet clay on the wheel and shaped it into a bowl.','陶工把湿黏土放在陶轮中央，塑造成一个碗。','potter centered the clay','noun subject','A potter makes vessels and other objects from clay.'),M('The potter shaped the bowl by mailing a postcard to the clay.','The potter shaped the bowl by turning and molding the clay.','A potter works clay into objects; mailing a postcard is unrelated.','meaning'),[Q(1,'What did the potter shape?','a clay bowl','a postal code','a feather','Potters shape clay vessels.'),Q(1,'What tool supported the shaping?','a pottery wheel','a mail truck','a power unit','The example says the clay was centered on a wheel.'),Q(1,'Who is a potter?','a craft worker who makes clay objects','a postal manager','a poultry farmer','The source definition identifies a clay craftsperson.'),Q(1,'What does the potter do to clay?','shapes and fires it','pollinates it','postdates it','Pottery craft involves forming and firing clay.')]);
P('pottery','From potter + -y, a collective noun for clay vessels, the craft of making them, or a workshop.',[C('pottery.s1','objects','The museum displayed pottery from three ancient coastal settlements.','博物馆展出了三个古代沿海聚落的陶器。','displayed pottery','mass noun object','Pottery can mean pots, plates, and other baked-clay objects.'),C('pottery.s2','craft','She studied pottery and learned to center clay on a wheel.','她学习制陶，学会把黏土置于陶轮中央。','studied pottery','verb + object','Pottery is also the craft of shaping and firing clay.'),C('pottery.s3','workshop','The village pottery employs six craftspeople who make bowls by hand.','村里的陶器作坊雇用了六名手工制作碗具的工匠。','village pottery','noun subject','Pottery can refer to the place where clay objects are made.')],M('She studied pottery by learning how to deliver letters for the post office.','She studied pottery by learning how to shape and fire clay.','Pottery as a craft is making clay objects, not delivering mail.','meaning'),[Q(1,'What did the museum display?','clay vessels and objects','mailing labels','a potato harvest','Pottery can mean objects made of baked clay.'),Q(2,'What did she learn in pottery class?','to center clay on a wheel','to sort letters','to measure a postcode','Pottery is the craft of forming clay.'),Q(3,'What does “the village pottery” mean?','a workshop where clay goods are made','a collection of postal stamps','a kind of poultry','Pottery can name a place of production.'),Q(1,'Which item is pottery?','a fired clay bowl','a paper postcard','a metal power unit','Pottery consists of objects made from baked clay.')]);
P('pouch','From French poche “pocket,” perhaps through a northern French form; the exact route into English is uncertain.',C('pouch.s1','travel','She kept the passport in a small pouch clipped inside her backpack.','她把护照放在夹扣于背包内侧的小袋里。','in a small pouch','prepositional phrase','A pouch is a small bag for holding items.'),M('He stored the passport in a pouch by leaving it loose on the pavement.','He stored the passport in a pouch, a small bag clipped inside his backpack.','A pouch is a small container; leaving the passport loose is not storing it in one.','meaning'),[Q(1,'What held the passport?','a small bag','a cooking pot','a power unit','Pouch means a small bag for keeping things.'),Q(1,'Where was the pouch clipped?','inside the backpack','on the postal truck','under the pavement','The context places it inside the backpack.'),Q(1,'Which item could be a pouch?','a small zippered bag','a large public poster','a garden prairie','A pouch is a small container.'),Q(1,'Why use a pouch for a passport?','to keep it safely contained','to cook it','to measure its power','The bag keeps the important item together and protected.')]);
P('poultry','From Old French pouletrie, based on poulet “young chicken,” from Latin pullus “young animal.”',[C('poultry.s1','farming','The farm raises poultry, including chickens, ducks, and turkeys.','农场饲养家禽，包括鸡、鸭和火鸡。','raises poultry','verb + object','Poultry can mean farm birds kept for eggs or meat.'),C('poultry.s2','food','The restaurant serves poultry with roasted vegetables and rice.','这家餐馆供应禽肉，搭配烤蔬菜和米饭。','serves poultry','verb + object','Poultry also refers to the meat from those birds.')],M('The farm raises poultry such as chickens and ducks, but no birds are kept there.','The farm raises poultry such as chickens and ducks.','Poultry means farm birds; the correction removes the contradiction.','meaning'),[Q(1,'Which animals are poultry?','chickens and ducks','potatoes and carrots','prawns and mussels','Poultry includes farm birds such as chickens and ducks.'),Q(2,'What does poultry mean on the restaurant menu?','meat from farm birds','a bird’s nest','a postal service','Poultry can mean the meat of chickens, ducks, or turkeys.'),Q(1,'What does the farm raise?','birds kept for eggs or meat','only wild whales','clay pots','The farming sense names domesticated birds.'),Q(2,'Which dish contains poultry?','roast turkey','mashed potato only','a ceramic bowl','Turkey meat is poultry.')]);
P('pounce','Probably from French poncer, “to seize” or a hunting term; the exact development into the English verb is uncertain.',C('pounce.s1','animals','The cat pounced on the toy mouse as soon as it darted beneath the chair.','玩具老鼠一钻到椅子下，猫就猛扑过去。','pounced on the toy mouse','verb + on','Pounce means spring forward quickly to seize prey or an opportunity.'),M('The cat pounced on the toy by moving away slowly and never touching it.','The cat pounced on the toy with a sudden leap.','To pounce is to spring quickly toward and seize something.','meaning'),[Q(1,'What did the cat do?','leapt suddenly toward the toy','walked slowly away','mailed a postcard','Pounce describes a quick spring toward something.'),Q(1,'What can an animal pounce on?','prey','a postal fee','a pottery class','The verb often describes seizing prey.'),Q(1,'Which action is a pounce?','a sudden leap to grab a toy','a slow stroll past it','a quiet nap','Pounce implies sudden movement and an attempt to seize.'),Q(1,'What does “pounce on an opportunity” mean?','act quickly to seize it','delay until it disappears','measure its weight','The word extends to quickly taking advantage of an opportunity.')]);
P('pound','The weight unit comes through Old English pund from Latin pondus “weight”; the British currency name also developed from a pound of silver; the striking verb has a separate history.',[C('pound.s1','currency','The book cost twelve pounds, including delivery to her flat.','这本书连同送到公寓的运费共花了十二英镑。','twelve pounds','count noun','Pound is the basic unit of British currency.'),C('pound.s2','measurement','The recipe calls for one pound of flour and half a pound of butter.','食谱需要一磅面粉和半磅黄油。','one pound of flour','measure phrase','A pound is a unit of weight equal to 16 ounces.'),C('pound.s3','sound and movement','Rain pounded against the windows throughout the night.','整夜雨点猛烈敲打着窗户。','pounded against the windows','verb + against','As a verb, pound means hit repeatedly or heavily.')],M('The recipe calls for one pound of flour, which is about 0.45 grams.','The recipe calls for one pound of flour, which is about 0.45 kilograms.','A pound is about 0.45 kilograms, not a fraction of a gram.','meaning'),[Q(1,'How much did the book cost?','twelve units of British currency','twelve kilograms','twelve postcards','Pound can mean the UK currency unit.'),Q(2,'What quantity of flour does the recipe need?','one pound','one postcard','one power unit','A pound is a measure of weight.'),Q(3,'What did the rain do to the windows?','hit them repeatedly and heavily','polish them gently','postdate them','Pound as a verb means strike repeatedly.'),Q(2,'About how much is one pound in metric weight?','0.45 kilograms','16 kilograms','0.45 grams','One pound is approximately 0.45 kg.')]);
P('pour','From Old French purer, “to pour,” of uncertain deeper origin; the verb extends from flowing liquid to heavy rain and crowds.',[C('pour.s1','cooking','Pour the warm broth slowly into the bowl so it does not splash.','把温热的肉汤慢慢倒进碗里，以免溅出来。','pour the broth into','verb + object + preposition','The basic sense makes liquid flow out of a container.'),C('pour.s2','weather','It poured all afternoon, so the match was moved indoors.','整个下午都在下倾盆大雨，因此比赛改到室内。','poured all afternoon','intransitive weather verb','When rain pours, it falls heavily.'),C('pour.s3','movement','Fans poured through the gates when the doors opened.','大门打开时，球迷们蜂拥穿过入口。','poured through the gates','plural subject + verb','People can pour in a large continuous stream.')],M('She poured the broth by keeping it sealed inside the pot.','She poured the broth by letting it flow from the pot into the bowl.','Pour means cause a liquid to flow out of its container.','meaning'),[Q(1,'What did she pour?','warm broth','rainfall totals','the crowd','Pour means make liquid flow from a container.'),Q(2,'What did the weather do?','rain heavily','shine all afternoon','freeze the match','It poured is an idiom for heavy rain.'),Q(3,'How did the fans move?','in a large continuous stream','one at a time in silence','backward into the street','People can pour through an opening in large numbers.'),Q(1,'What does “pour the liquid into a bowl” mean?','make it flow from one container to another','freeze it in place','weigh the bowl','The basic verb sense is transfer flowing liquid.')]);
P('poverty','From Old French poverte, from Latin paupertas “being poor,” based on pauper “poor.”',C('poverty.s1','society','The program offers job training and childcare to families living in poverty.','这项计划为生活贫困的家庭提供职业培训和托儿服务。','living in poverty','fixed prepositional phrase','Poverty is the state of having very little money or resources.'),M('The family lived in poverty because it had more wealth than it could spend.','The family lived in poverty because it lacked enough money for basic needs.','Poverty means severe lack of money or resources.','meaning'),[Q(1,'Who does the program help?','families with very limited resources','families with unlimited wealth','postal workers only','Poverty is the state of being very poor.'),Q(1,'What services does the program offer?','job training and childcare','a pottery wheel and postage','a power unit','The example specifies practical support for families.'),Q(1,'Which phrase is closest to poverty?','severe economic hardship','a strong argument','a scenic plain','Poverty concerns material deprivation.'),Q(1,'What does “living in poverty” describe?','a state of being very poor','a brief visit to a post office','a way of cooking potatoes','The noun names a condition of lacking resources.')]);
P('powder','From Old French poudre, from Latin pulvis “dust”; the word names fine particles or a cosmetic/medical substance.',[C('powder.s1','materials','The crushed chalk became a fine powder that coated the workbench.','粉笔被压碎成细粉，覆盖在工作台上。','fine powder','noun complement','Powder is a dry substance of tiny loose grains.'),C('powder.s2','medicine','She applied the medicated powder to the irritated skin as directed.','她按说明把药粉涂在发炎的皮肤上。','medicated powder','adjective + noun','Powder can be a cosmetic or medical product put on the skin.'),C('powder.s3','preparation','Grind the dried herbs to powder before adding them to the sauce.','把干香草磨成粉末，再加入酱汁。','grind the herbs to powder','verb + object + complement','The verb can mean crush something into powder.')],M('The pharmacist sold a powder that was one large solid stone.','The pharmacist sold a powder made of very fine dry particles.','Powder consists of small loose grains, not a single solid stone.','meaning'),[Q(1,'What covered the workbench?','fine particles of chalk','a postcard','a liquid potion','Powder is a dry substance made of tiny grains.'),Q(2,'Where was the medicated powder applied?','on irritated skin','inside a letter','on a power unit','This sense is a medical product used on skin.'),Q(3,'What does “grind the herbs to powder” mean?','crush them into fine particles','pour water over them','plant them in a pot','The verb means turn something into powder.'),Q(1,'Which item is powder?','a loose dry fine-grained substance','a single large stone','a solid metal bar','Powder is made of many small grains.')]);
P('power','From Old French poer, from Latin posse “to be able”; senses include ability, authority, electrical energy, and providing energy.',[C('power.s1','ability','The rescue team had the power to reopen the road once the slope was secure.','边坡安全后，救援队有权重新开放道路。','had the power to reopen','noun + infinitive','Power can mean ability or authority to act.'),C('power.s2','government','The constitution limits the power of each branch of government.','宪法限制政府各部门的权力。','power of each branch','of-phrase','This sense is control over people or public affairs.'),C('power.s3','electricity','The storm cut power to hundreds of homes overnight.','暴风雨夜间切断了数百户家庭的电力。','cut power to','verb + object + preposition','Power can mean electricity that runs machines and homes.'),C('power.s4','engineering','A small battery powers the sensor for several months.','一节小电池可为传感器供电数月。','battery powers the sensor','subject + verb + object','As a verb, power means supply a machine with energy.')],M('The storm cut power to the homes by supplying them with uninterrupted electricity.','The storm cut power to the homes by interrupting their electricity supply.','To cut power is to stop the electricity supply, not provide it.','meaning'),[Q(1,'What could the rescue team do?','reopen the road when it was safe','electrify the slope','write the constitution','Power can mean authority or ability.'),Q(2,'What does the constitution limit?','governmental control','the electricity bill','the battery size','Power can mean authority over public affairs.'),Q(3,'What did the storm cut?','electricity','the road’s legal authority','the sensor’s report','Power as a noun can mean electrical energy.'),Q(4,'What did the battery do?','supplied energy to the sensor','took authority from the sensor','measured the slope','To power a device is to provide its energy.')]);
P('power unit','A compound phrase: power + unit; the unit is a standardized quantity used to measure power.',C('power unit.s1','physics','The watt is the SI power unit used to rate the motor’s output.','瓦特是国际单位制中的功率单位，用来标示电动机的输出。','power unit','noun complement','A power unit measures the rate of energy transfer.'),M('The watt is a power unit that measures the mass of a motor.','The watt is a power unit that measures the motor’s rate of energy output.','A watt measures power, not mass.','meaning'),[Q(1,'What does the watt measure?','power output','postal weight','temperature only','A watt is a unit of power.'),Q(1,'What does the motor rating express?','its output power','its color','its postal address','Power units quantify energy transfer per unit time.'),Q(1,'Which is a power unit?','watt','pound of flour','postcode','The watt is the SI unit for power.'),Q(1,'What is a unit in this phrase?','a standardized measure','a person who repairs motors','a type of battery','A unit is a defined measure of a quantity.')]);
P('powerful','From power + -ful, “full of power”; it describes great force, influence, or effect.',C('powerful.s1','technology','The powerful turbine continued generating electricity through the storm.','这台强劲的涡轮机在暴风雨中仍持续发电。','powerful turbine','adjective before noun','Powerful means having great power or influence.'),M('The powerful turbine could not turn even a tiny wheel.','The powerful turbine could turn the generator under heavy load.','Powerful describes great force or capacity, not inability to do work.','meaning'),[Q(1,'What did the turbine keep generating?','electricity','postage','poultry','Powerful describes a machine with great capacity.'),Q(1,'Which machine is powerful?','one able to drive a heavy generator','one unable to turn a small wheel','one that is only decorative','The adjective means having great power.'),Q(1,'What conditions did the turbine operate through?','a storm','a pottery class','a postal exam','The example emphasizes its strength in harsh conditions.'),Q(1,'Choose a close synonym for powerful.','strong','weak','unrelated','Powerful means strong or influential.')]);
P('powerfully','From powerful + adverb suffix -ly; it means with strength, intensity, or a strong effect.',C('powerfully.s1','writing','The final scene powerfully conveyed the cost of the family’s separation.','最后一幕有力地表现了这个家庭分离所付出的代价。','powerfully conveyed','adverb modifying verb','Powerfully describes an action with strong effect or intensity.'),M('The scene powerfully affected no one and left every viewer entirely unmoved.','The scene powerfully affected viewers and left a lasting impression.','Powerfully means with a strong effect, contrary to leaving everyone unaffected.','meaning'),[Q(1,'How did the scene convey the cost?','with strong emotional effect','with no effect','by measuring it in watts','Powerfully means with intensity or impact.'),Q(1,'Which word does powerfully modify?','conveyed','scene','family','The adverb modifies the verb conveyed.'),Q(1,'Which action is done powerfully?','a speech that strongly moves its listeners','a sentence no one can hear','a quiet list of unrelated dates','Powerfully can describe a strong effect on people.'),Q(1,'What does powerfully mean here?','with a strong impact','after the war','in a small pouch','The example uses the figurative impact sense.')]);
P('ppm','An initialism of parts per million, a ratio expressing how many parts of one substance occur in one million parts of a mixture.',C('ppm.s1','measurement','The sensor recorded carbon dioxide at 420 ppm in the greenhouse air.','传感器测得温室空气中的二氧化碳浓度为420 ppm。','at 420 ppm','measurement phrase','PPM expresses a very small concentration as parts in one million.'),M('The report used ppm to mean parts per hundred and multiplied the concentration by ten thousand.','The report used ppm to mean parts per million.','The final m stands for million, not hundred.','measurement'),[Q(1,'What does ppm stand for?','parts per million','postage per meter','plants per month','PPM is an initialism for parts per million.'),Q(1,'What did the sensor measure?','carbon dioxide concentration','the number of postal workers','the motor’s power unit','The example gives a gas concentration.'),Q(1,'How many total parts form the denominator in ppm?','one million','one hundred','one thousand','The abbreviation explicitly refers to a million parts.'),Q(1,'Which notation could express a trace contaminant?','12 ppm','12 p.m.','12 pounds','PPM is used for small concentrations in mixtures.')]);
P('practicable','From practic(e) + -able, ultimately from Greek praktikos “fit for action”; it means capable of being put into practice.',C('practicable.s1','planning','The engineer proposed a practicable repair that the town could complete with its current tools.','工程师提出了一项可行的维修方案，镇里用现有工具就能完成。','practicable repair','adjective before noun','Practicable means feasible under real conditions.'),M('The repair was practicable even though it required a machine the town could never obtain.','The repair was practicable because the town already had the needed tools.','A practicable plan can actually be carried out with available resources.','meaning'),[Q(1,'Why was the repair practicable?','the town had the tools needed','the required machine was impossible to obtain','the plan had no steps','Practicable means feasible under actual conditions.'),Q(1,'Which plan is practicable?','one that can be completed with available resources','one that relies on nonexistent equipment','one that cannot be attempted','The adjective means possible to put into practice.'),Q(1,'Choose the closest meaning of practicable.','feasible','imaginary','inevitable','Practicable means capable of being done.'),Q(1,'What does the suffix -able convey?','capability or possibility','a past action','a plural group','-able means able to be done.')]);
P('practical','From Latin practicus and Greek praktikos “concerned with action,” based on prassein “to do.”',[C('practical.s1','education','The course combines practical workshop sessions with lectures on design theory.','课程把实践工作坊与设计理论讲座结合起来。','practical workshop sessions','adjective before noun','This sense contrasts real action with abstract ideas.'),C('practical.s2','problem-solving','A practical solution would reuse the existing pipes instead of replacing the whole system.','切实可行的办法是重复利用现有管道，而不是更换整个系统。','practical solution','adjective before noun','Practical can mean useful and likely to work in real life.'),C('practical.s3','skills','Mina is practical and can repair a chair with simple tools.','米娜动手能力强，用简单工具就能修好椅子。','is practical','linking verb + adjective','The adjective can describe a person skilled at making or fixing things.')],M('Mina is practical because she cannot repair or make anything, even with the right tools.','Mina is practical because she can repair the chair with simple tools.','A practical person is good at handling real tasks and repairs.','meaning'),[Q(1,'What does the course add to theory?','hands-on workshops','a postal code','a potted plant','Practical sessions involve real activity.'),Q(2,'Why reuse the pipes?','it is a workable solution','the pipes are impossible to use','the system is a poem','Practical can mean useful and feasible.'),Q(3,'Why is Mina practical?','she can repair a chair','she avoids every task','she only studies abstractions','This sense describes someone good at hands-on work.'),Q(1,'Which example is practical learning?','building and testing a small bridge','memorizing a list without applying it','reading a postcard','Practical concerns action and real situations.')]);
P('practicality','From practical + -ity, a noun suffix for a quality; it means usefulness or a concrete real-world concern.',[C('practicality.s1','design','The practicality of the raincoat became clear during the sudden downpour.','突如其来的暴雨显出了这件雨衣的实用性。','practicality of the raincoat','of-phrase','This sense is the quality of being useful in real circumstances.'),C('practicality.s2','planning','Before booking the trip, they discussed practicalities such as visas and transport.','预订旅行前，他们讨论了签证和交通等实际细节。','discussed practicalities','plural noun object','Practicalities are concrete details that need to be handled.')],M('They discussed the practicalities of the trip but ignored concrete matters like visas and transport.','They discussed practicalities such as visas and transport.','Practicalities are the real details that must be dealt with.','meaning'),[Q(1,'What became clear in the downpour?','the raincoat’s usefulness','its postage cost','its political power','Practicality is usefulness in real conditions.'),Q(2,'Which matters did they discuss?','visas and transport','abstract poems only','the raincoat’s color only','Practicalities are concrete arrangements.'),Q(1,'What does practicality measure?','how well something works in real life','how colorful it is','how old it is','The noun means practical usefulness.'),Q(2,'Which are travel practicalities?','tickets and local transport','the idea of travel in general','a fictional potion','These are concrete details to arrange.')]);
P('practically','From practical + -ly; it means either “in a useful real-world way” or, by extension, “almost.”',[C('practically.s1','degree','By the time we reached the station, the platform was practically empty.','我们到车站时，站台几乎空无一人。','practically empty','adverb modifying adjective','This common sense means almost or nearly.'),C('practically.s2','method','The guide explained how to practically apply the safety checklist during a shift.','指南说明了如何在轮班期间实际运用安全清单。','practically apply','adverb modifying verb','The other sense means in a useful, real-world manner.')],M('The platform was practically empty, meaning every seat and standing space was packed.','The platform was practically empty, with almost nobody there.','Practically means nearly in this sentence, not completely full.','meaning'),[Q(1,'How full was the platform?','almost empty','completely packed','under construction','Practically can mean nearly.'),Q(2,'How should staff use the checklist?','in real working conditions','only as an abstract theory','as a postage stamp','Practically can mean in a useful, real-world way.'),Q(1,'Which sentence uses practically to mean almost?','The task is practically finished.','She practically used a wrench.','The practicalities are listed.','Practically finished means nearly finished.'),Q(2,'Which sentence uses the practical-method sense?','He practically tested the device in the workshop.','It is practically midnight.','The platform is practically empty.','The first describes real-world testing.')]);
P('practice','From Old French practice/pratiser and Medieval Latin practicare “do, perform”; these derive from Late Latin practicus and Greek praktikos “practical.” American English uses practice for both noun and verb.',[C('practice.s1','training','Daily piano practice helped Jo play the difficult passage accurately.','每天练习钢琴帮助乔准确演奏这段困难乐句。','piano practice','noun + modifier','As a noun, practice can mean repeated training.'),C('practice.s2','application','The policy sounds simple in theory but is difficult in practice.','这项政策理论上听起来简单，实践中却很难。','in practice','fixed phrase','Practice can mean real-world application.'),C('practice.s3','training','The goalkeeper practices penalty saves after every team session.','每次团队训练后，守门员都会练习扑点球。','practices penalty saves','third-person verb','In American usage, practice is also the verb meaning train repeatedly.')],M('Her daily practice improved her piano skills because she never played or trained.','Her daily practice improved her piano skills because she rehearsed the passage.','Practice as a noun is repeated training that develops skill.','meaning'),[Q(1,'What improved Jo’s playing?','daily piano training','a postal delivery','a pottery glaze','Practice as a noun can mean repeated training.'),Q(2,'What does “in practice” mean?','in real use','in a theoretical plan only','in a cooking pot','The phrase refers to actual application.'),Q(3,'What does the goalkeeper do?','repeats penalty saves to improve','sends a postcard','measures a power unit','Practice as a verb means train repeatedly.'),Q(1,'Which spelling can be a verb in American English?','practice','practise only','practically','American English uses practice for both noun and verb.')]);
P('practise','British spelling of the verb related to practice, from Greek praktikos “concerned with action”; practise means train, apply, or work in a profession.',[C('practise.s1','training','The choir will practise the new harmony before the concert.','合唱团将在音乐会前练习新的和声。','will practise the harmony','modal + verb + object','The verb means repeat an activity to improve skill.'),C('practise.s2','habit','He practises patience by listening before he responds.','他通过先倾听再回应来践行耐心。','practises patience','verb + object','Practise can mean put a belief or quality into action.'),C('practise.s3','profession','After qualifying, she practised law in a small coastal town.','取得资格后，她在一个海滨小镇从事法律工作。','practised law','verb + profession','The verb can mean work in a profession.')],M('The choir will practise the harmony by refusing to sing or rehearse it.','The choir will practise the harmony by rehearsing it together.','To practise a musical part is to rehearse it repeatedly.','meaning'),[Q(1,'What will the choir practise?','the new harmony','a postcode','a cooking pot','Practise means rehearse an activity.'),Q(2,'How does he practise patience?','by listening before responding','by interrupting everyone','by mailing a letter','This sense means act according to a quality or belief.'),Q(3,'What did she do after qualifying?','worked as a lawyer','became a postmaster','made pottery','Practise law means work as a lawyer.'),Q(1,'In British English, which spelling is the verb?','practise','practice only','practitioner','British usage distinguishes practise (verb) from practice (noun).')]);
P('practitioner','From practice + agent suffix -er, through Latin practica; it names someone who works in a profession or regularly follows a method.',[C('practitioner.s1','healthcare','The practitioner reviewed the patient’s symptoms and explained the treatment options.','执业医师查看了患者的症状，并解释了治疗方案。','practitioner reviewed','noun subject','A practitioner is a skilled professional, especially a doctor.'),C('practitioner.s2','methods','As a practitioner of meditation, Amir sets aside ten minutes each morning.','作为冥想的实践者，阿米尔每天早上留出十分钟。','practitioner of meditation','of-phrase','The word also names someone who regularly carries out an activity.')],M('The practitioner treated the patient despite having no training or professional role.','The practitioner treated the patient as a trained professional.','A practitioner is someone who works in a skilled profession or practices a method.','meaning'),[Q(1,'What did the practitioner review?','the patient’s symptoms','the postal schedule','a pottery wheel','The healthcare practitioner is a professional.'),Q(2,'What does Amir regularly do?','meditation','postal delivery','potassium testing','A practitioner can be someone who regularly follows a practice.'),Q(1,'Which person is a practitioner?','a licensed clinician treating patients','a patient’s postcard','a power unit','The source sense is a person working in a skilled profession.'),Q(2,'What does “practitioner of meditation” mean?','someone who regularly meditates','someone who sells meditation books only','someone who avoids meditation','A practitioner carries out the activity.')]);
P('pragmatic','From Greek pragmatikos “relating to deeds,” based on pragma “deed, act”; the adjective favors what works in practice.',C('pragmatic.s1','decision-making','Rather than wait for a perfect design, the team chose a pragmatic fix that could be installed today.','团队没有等待完美设计，而是选择了今天就能安装的务实方案。','pragmatic fix','adjective before noun','Pragmatic focuses on practical results rather than abstract ideals.'),M('The team made a pragmatic choice by rejecting the only solution that could work in practice.','The team made a pragmatic choice by selecting the fix that could be installed today.','A pragmatic choice considers what will work under real conditions.','meaning'),[Q(1,'Why was the fix pragmatic?','it could be installed today','it was perfect in theory but impossible','it required no decision','Pragmatic means focused on workable practical results.'),Q(1,'Which person is pragmatic?','someone who chooses a workable option','someone who rejects every useful solution','someone who values only an abstract ideal','The adjective describes attention to practical outcomes.'),Q(1,'What did the team prioritize?','a solution that works now','a design that cannot be built','a longer discussion only','A pragmatic approach focuses on what can be done.'),Q(1,'Choose a close meaning of pragmatic.','practical','impractical','imaginary','Pragmatic concerns real-world action.')]);
P('prairie','From French prairie “meadow,” from Old French praierie, related to Latin pratum “meadow.”',C('prairie.s1','geography','A herd of bison moved across the wide North American prairie.','一群野牛穿过广阔的北美大草原。','North American prairie','noun modifier','A prairie is a broad, usually flat grassland in North America.'),M('The bison crossed a dense tropical rainforest prairie covered by a closed canopy.','The bison crossed a wide, open grassland prairie.','Prairie is open grassland, not a dense rainforest.','meaning'),[Q(1,'What landscape did the bison cross?','open grassland','a deep ocean trench','a city street','A prairie is a broad area of grassland.'),Q(1,'Where are prairies especially associated?','North America','the center of the Pacific Ocean','the Arctic sea floor','The source definition specifies North American grassland.'),Q(1,'Which scene is a prairie?','a broad plain covered mostly with grass','a steep coral reef','a crowded underground tunnel','Prairies are open grassy plains.'),Q(1,'What animal moved across the prairie?','bison','prawns','pigeons','The context names a herd of bison.')]);
P('prairies','Plural of prairie; from French prairie “meadow,” related to Latin pratum “meadow.”',C('prairies.s1','geography','In spring, wildflowers spread across the prairies of the central plains.','春天，野花遍布中部平原的大草原。','across the prairies','plural noun','Prairies are wide, mostly treeless grass-covered plains.'),M('The prairies were thickly forested with no open grassland.','The prairies were broad, mostly treeless grasslands.','Prairies are open plains, usually dominated by grass rather than dense forest.','meaning'),[Q(1,'What spread across the plains?','wildflowers','postal notices','potted ferns indoors','The example describes flowers growing across grasslands.'),Q(1,'What are prairies?','wide open grass-covered plains','deep lakes','mountain peaks covered in ice','The source defines prairie as broad grassland.'),Q(1,'Why is the word prairies plural?','it refers to more than one prairie','it is a verb in past tense','it means a single flower','The -s marks the plural noun.'),Q(1,'Which phrase describes prairies?','mostly treeless grasslands','dense tropical forests','submerged reefs','Prairies are generally open and grassy.')]);
P('praise','From Old French preisier/prisier “praise, value,” from Late Latin preciare/pretiare and Latin pretium “value, worth”; it means express approval or admiration.',[C('praise.s1','feedback','The coach praised the team for staying focused after the early setback.','教练称赞球队在早期受挫后仍保持专注。','praised the team for','verb + object + for','The verb means say that someone’s action is good.'),C('praise.s2','worship','The hymn praises the creator for the beauty of the natural world.','这首赞美诗颂扬造物主创造的自然之美。','praises the creator','verb + object','This sense is to speak of someone with strong respect or worship.'),C('praise.s3','approval','Her careful work earned praise from the review panel.','她细致的工作赢得了评审小组的赞扬。','earned praise','noun object','As a noun, praise is approval expressed in words.')],M('The coach praised the team for giving up as soon as the setback occurred.','The coach praised the team for staying focused after the setback.','Praise expresses approval; the corrected behavior is what the coach admired.','meaning'),[Q(1,'Why did the coach praise the team?','they stayed focused','they abandoned the match','they lost the schedule','Praise means express approval of good work or behavior.'),Q(2,'What does the hymn do?','speaks reverently of the creator','measures a prairie','sends a postcard','Praise can mean worshipful admiration.'),Q(3,'What did the review panel give?','approval in words','a pot of water','a postgraduate degree','Praise as a noun is expressed approval.'),Q(1,'Which sentence uses praise as a verb?','The teacher praised her careful solution.','The teacher received praise.','The teacher wrote a postscript.','The first has praise as an action verb.')]);
P('praised','Past participle of praise; as an adjective it means receiving approval or admiration.',C('praised.s1','recognition','The praised engineer credited the whole repair crew rather than taking sole credit.','受到称赞的工程师把功劳归于整个维修团队，而没有独揽其功。','praised engineer','adjective before noun','Praised describes a person or thing that has received praise.'),M('The praised engineer received no approval or positive comments from anyone.','The praised engineer received recognition for the successful repair.','Praised means that someone has been spoken of approvingly.','meaning'),[Q(1,'What had the engineer received?','approval for the repair','a postcode','a cooking pot','Praised means receiving praise or recognition.'),Q(1,'What did the engineer do with the credit?','shared it with the crew','claimed no repair happened','mailed it to the clinic','The example says the engineer credited the whole crew.'),Q(1,'Which person is praised?','someone commended for good work','someone whose work is ignored','someone who delivers mail','Praised means spoken of favorably.'),Q(1,'What is the grammatical role of praised here?','an adjective describing engineer','a noun naming the repair','an adverb modifying credited','It appears before the noun as an adjective.')]);
P('pram','A colloquial shortening of perambulator, attested for a baby carriage by the 19th century; perambulate comes from Latin perambulare “walk through,” from per- + ambulare “walk.” The shortening may also have been influenced by an older word for a flat-bottomed boat.',C('pram.s1','family','He pushed the sleeping baby along the park path in a pram.','他把熟睡的婴儿放在婴儿车里，沿公园小路推行。','in a pram','prepositional phrase','A pram is a wheeled carriage in which a baby lies and is pushed.'),M('She carried the baby in a pram by holding the carriage in her arms without wheels.','She pushed the baby in a wheeled pram along the path.','A pram is a wheeled carriage pushed along, not simply carried.','meaning'),[Q(1,'Where was the baby?','in a wheeled carriage','in a pottery jar','in a postal box','A pram is a baby carriage.'),Q(1,'What did the adult do with it?','pushed it along the path','poured it into a bowl','postdated it','The example says he pushed the pram.'),Q(1,'What does pram abbreviate historically?','perambulator','postmaster','practitioner','Pram is a shortened form of perambulator.'),Q(1,'Which item is a pram?','a wheeled baby carriage','a child’s postage stamp','a unit of power','The source sense is a carriage for a baby.')]);

P('prank','The origin is uncertain; the noun developed in 17th-century English for a trick or mischievous act.',C('prank.s1','social life','Her friends planned a harmless prank by replacing the meeting room’s welcome sign with a silly drawing.','朋友们计划了一个无伤大雅的恶作剧：把会议室的欢迎牌换成滑稽的画。','planned a harmless prank','noun + modifier','A prank is a trick meant to surprise or amuse someone.'),M('They called it a prank, but it involved damaging a stranger’s car.','They called it a harmless prank because it only surprised their friend.','A prank is a trick; serious property damage is not harmless.','meaning'),[Q(1,'What did the friends plan?','a harmless trick','a formal election','a postal delivery','A prank is a trick done to surprise someone.'),Q(1,'What did they replace?','the welcome sign','the whole meeting room','a postage label','The context specifies the sign.'),Q(1,'Which action is a prank?','hiding a friend’s umbrella as a joke','stealing a neighbor’s car','repairing a broken road','A prank is a mischievous trick, often intended as a joke.'),Q(1,'What does harmless suggest about this prank?','it caused no serious harm','it involved injury','it destroyed property','The example describes a light joke.')]);
P('prate','From Middle English praten, perhaps imitative of foolish chatter; the precise origin is uncertain.',C('prate.s1','conversation','Instead of answering the question, the witness prated about unrelated office gossip for twenty minutes.','证人没有回答问题，而是絮絮叨叨地讲了二十分钟无关的办公室八卦。','prated about gossip','verb + about','Prate means talk foolishly or at length about something unimportant.'),M('The witness prated by giving a concise, relevant answer in one sentence.','The witness prated by rambling at length about unrelated gossip.','Prate means foolish, prolonged chatter, not a concise relevant answer.','meaning'),[Q(1,'What did the witness do?','chattered at length about gossip','answered directly','delivered a package','Prate means talk foolishly and at length.'),Q(1,'What was the gossip’s relation to the question?','it was unrelated','it was the exact answer','it was a court order','The context calls it unrelated office gossip.'),Q(1,'Which verb is closest to prate?','babble','whisper a clear answer','measure','Prate describes foolish or excessive talk.'),Q(1,'What made the speech prating?','it rambled for twenty minutes','it answered in one word','it contained a clear conclusion','The length and irrelevant chatter fit prate.')]);
P('prattle','From prate + a frequentative -le, suggesting repeated or ongoing chatter; the form may also have sound-imitative influence.',C('prattle.s1','family','The toddler prattled happily about the toy train while her parents packed the car.','父母收拾车时，蹒跚学步的孩子开心地絮叨着玩具火车。','prattled happily about','verb + about','Prattle is continuous light chatter, often childlike.'),M('The toddler prattled by remaining completely silent for the whole afternoon.','The toddler prattled by chattering happily about her toy.','Prattle means chatter, so silence contradicts the verb.','meaning'),[Q(1,'What did the toddler do?','chattered about a toy train','drove the car','read a postal code','Prattle means talk continuously in a light or childlike way.'),Q(1,'What tone does prattled happily suggest?','cheerful chatter','a formal lecture','angry silence','The adverb marks the child’s light, happy chatter.'),Q(1,'Which person might prattle?','a young child talking excitedly','a silent statue','a postal sorting machine','Prattle is often used for childlike chatter.'),Q(1,'What does prattle emphasize?','ongoing, often light talk','a single written note','a sudden leap','The verb describes continuing chatter.')]);
P('prawn','Recorded in English as a name for a shrimp-like shellfish; its deeper origin is uncertain.',C('prawn.s1','food','The chef grilled each prawn briefly and served it with lemon and herbs.','厨师把每只大虾快速烤熟，配上柠檬和香草。','grilled each prawn','verb + object','A prawn is an edible shellfish resembling a small lobster or shrimp.'),M('The chef grilled each prawn after removing its feathers and beak.','The chef grilled each prawn after cleaning its shell.','A prawn is a shellfish, not a bird with feathers and a beak.','meaning'),[Q(1,'What did the chef grill?','a shellfish','a postcard','a pottery bowl','Prawn names an edible shellfish.'),Q(1,'What did the chef serve with it?','lemon and herbs','postage and a postcode','a power unit','The context pairs the seafood with lemon and herbs.'),Q(1,'Which animal is a prawn?','a shrimp-like crustacean','a farm bird','a small mammal','Prawns are shellfish.'),Q(1,'How was it cooked?','briefly on a grill','in a potted plant','by mailing it','The sentence says the chef grilled it briefly.')]);
P('pray','From Old French preier, from Latin precari “to entreat or ask earnestly”; senses include religious prayer and earnest hope.',[C('pray.s1','religion','The family gathered to pray for the injured climber’s recovery.','一家人聚在一起，为受伤登山者康复祈祷。','pray for recovery','verb + for','The religious sense is speaking to a god to give thanks or ask for help.'),C('pray.s2','hope','I pray that the river stays below the flood barrier tonight.','我恳切希望河水今晚不要漫过防洪堤。','pray that the river stays','verb + that-clause','The extended sense means hope for something intensely.')],M('They prayed for the climber by asking the river to rise and worsen the danger.','They prayed for the climber’s safe recovery.','Prayer in this context is a request for help, not for greater danger.','meaning'),[Q(1,'What did the family do?','asked God for the climber’s recovery','measured the climber’s weight','mailed the climber a postcard','Pray can mean speak to God to ask for help.'),Q(2,'What does the speaker earnestly hope?','the river stays below the barrier','the barrier collapses','the climber is lost','Pray can mean hope very strongly.'),Q(1,'Which phrase commonly follows pray in this sense?','pray for someone','prate at someone','pounce someone','The sentence uses pray for a person’s recovery.'),Q(2,'Which sentence uses the hope sense?','I pray the storm passes by morning.','They prayed in the chapel.','The prayer was printed.','The first expresses an intense hope.')]);
P('prayer','From pray + agent/action suffix -er, through French priere and Latin precaria; it names the act or words of praying.',C('prayer.s1','religion','She ended the prayer with a request for peace and strength for the community.','她以祈求社区获得和平与力量结束了祷告。','ended the prayer','verb + object','Prayer is either the act of praying or the words spoken.'),M('The prayer ended with the congregation refusing to say or think any words.','The prayer ended with the congregation saying words for peace.','A prayer is an act of praying or words said in prayer.','meaning'),[Q(1,'What did she ask for in the prayer?','peace and strength','a postal discount','a clay pot','A prayer can contain a request for help or blessing.'),Q(1,'What can prayer refer to?','the act or words of praying','a unit of electricity','a trick played on a friend','The noun covers both the activity and its words.'),Q(1,'Which phrase names a prayer?','a spoken appeal to God','a parcel label','a prairie grassland','Prayer is religious speech or the act of praying.'),Q(1,'How did the prayer end?','with a request for the community','with a potter’s wheel','with a postcode','The context says it ended with a request.')]);
P('pre-dated','Pre- “before” + dated, the past participle of date; the adjective describes a document assigned an earlier date or something earlier than a point in time.',C('pre-dated.s1','documents','The letter was pre-dated to Monday even though the clerk signed it on Wednesday.','这封信虽然周三签署，却被填上周一的日期。','was pre-dated to Monday','passive verb phrase','Pre-dated means given an earlier date than the actual one.'),M('The invoice was pre-dated to a Friday that came after the day it was issued.','The invoice was pre-dated to a Monday before it was issued on Wednesday.','Pre-dated means assigned a date earlier than the real date.','meaning'),[Q(1,'What date was written on the letter?','Monday','Wednesday','the following Friday','Pre-dated means assigned an earlier date.'),Q(1,'When was it actually signed?','Wednesday','Monday','the previous Friday','The context contrasts the written date with the signing date.'),Q(1,'What does pre- mean in pre-dated?','before','after','again','The prefix pre- means before.'),Q(1,'Which invoice is pre-dated?','one dated before it was actually issued','one dated a month afterward','one without any date','Pre-dated describes an earlier assigned date.')]);
P('pre-owned','Pre- “before” + owned; it is a polite commercial term for an item owned by someone else previously.',C('pre-owned.s1','shopping','The dealership inspected every pre-owned car before offering it for sale.','经销商在出售每辆二手车前都会进行检查。','pre-owned car','adjective before noun','Pre-owned means previously owned by another person.'),M('The dealer called a car pre-owned even though it had never belonged to anyone before.','The dealer called a car pre-owned because a previous owner had used it.','Pre-owned describes an item with a prior owner.','meaning'),[Q(1,'What does pre-owned mean?','previously owned by someone else','never manufactured','owned in the future','The adjective means owned before by another person.'),Q(1,'What did the dealership inspect?','used cars before resale','new postcards','potted potatoes','Pre-owned cars have had a prior owner.'),Q(1,'Why use pre-owned in an advertisement?','it describes a second-hand item politely','it says the item is handmade','it states the item is free','Pre-owned is a commercial term for previously owned goods.'),Q(1,'Which item is pre-owned?','a bicycle bought from its former owner','a brand-new bicycle in a factory','a bicycle not yet made','The term refers to prior ownership.')]);
P('preach','From Old English predician, from Latin praedicare “proclaim publicly,” formed from prae “before” + dicare “proclaim.”',[C('preach.s1','religion','The minister preached a sermon about forgiveness at Sunday service.','牧师在周日礼拜时讲了一篇关于宽恕的道。','preached a sermon','verb + object','The religious sense is deliver a talk about religion.'),C('preach.s2','advice','My brother keeps preaching about exercise, although he rarely takes a walk himself.','我哥哥总在宣扬锻炼的好处，自己却很少散步。','preaching about exercise','verb + about','The informal sense can mean bossily telling others what is right.')],M('The minister preached a sermon by discussing the weather without mentioning any religious ideas.','The minister preached a sermon about forgiveness and faith.','To preach a sermon is to give religious teaching.','meaning'),[Q(1,'What did the minister deliver?','a religious sermon','a postage fee','a pottery lesson','Preach can mean give a religious talk.'),Q(2,'Why does the brother sound hypocritical?','he urges exercise but rarely walks','he takes too many walks','he avoids discussing exercise','The figurative sense is often bossy moral advice.'),Q(1,'Where might a minister preach?','at a worship service','at a post office sorting mail','in a cooking pot','The source sense concerns religious teaching.'),Q(2,'What does “preach about exercise” mean here?','repeatedly tell others they should exercise','teach a formal religion service','mail a fitness plan','The informal use means urge or lecture others.')]);
P('preacher','From preach + agent suffix -er; it names someone who delivers religious teaching.',C('preacher.s1','religion','The preacher visited the village chapel to speak about compassion and service.','传道人来到村里的小教堂，讲述慈悲与服务。','preacher visited','noun subject','A preacher is a person who preaches a religion.'),M('The preacher addressed the congregation by delivering a lecture on postage rates only.','The preacher addressed the congregation with a religious message about compassion.','A preacher is a religious speaker; a talk solely about postage misses that role.','meaning'),[Q(1,'Who visited the chapel?','a person who preaches','a postal manager','a potter','Preacher names someone who delivers religious teaching.'),Q(1,'What did the preacher discuss?','compassion and service','power-unit conversion only','prawns','The example gives the topic of the religious talk.'),Q(1,'Which setting fits a preacher?','a chapel','a mail sorting room only','a factory floor','Preachers commonly speak in places of worship.'),Q(1,'Which job description matches preacher?','religious speaker','postal delivery worker','shellfish cook','The source sense is someone who preaches a religion.')]);
P('prearrange','Pre- “before” + arrange, from French arranger; it means settle details in advance.',C('prearrange.s1','planning','The organizers prearranged transport so the guests could leave immediately after the ceremony.','组织者预先安排了交通，因此来宾在仪式后可以立即离开。','prearranged transport','verb + object','Prearrange means make arrangements before an event.'),M('They prearranged the transport by waiting until after the ceremony to begin planning it.','They prearranged the transport before the ceremony.','Prearrange means arrange in advance, not afterward.','meaning'),[Q(1,'When did organizers arrange transport?','before the ceremony','after every guest had left','during the next holiday','Prearrange means settle details in advance.'),Q(1,'Why was transport arranged early?','guests could leave promptly','the ceremony had no guests','the postman needed a vehicle','The example states the purpose of prior planning.'),Q(1,'What does pre- mean in prearrange?','beforehand','afterward','together','The prefix pre- means before.'),Q(1,'Which task can be prearranged?','a pickup time for visitors','a decision already forgotten','a letter’s postscript after signing','Prearrange is to settle details in advance.')]);
P('precarious','From Latin precarius “obtained by asking or entreaty,” from precari “to pray”; the sense developed to something insecure or dependent on uncertain conditions.',C('precarious.s1','safety','The climber balanced on a precarious ledge with loose stones below her boots.','登山者站在一处岌岌可危的岩架上，脚下是松动的石块。','precarious ledge','adjective before noun','Precarious describes a position that is unsafe or likely to fail.'),M('The climber stood on a precarious ledge that was broad, stable, and completely secure.','The climber stood on a precarious ledge of loose stones that might give way.','Precarious means unsafe or unstable.','meaning'),[Q(1,'Why was the ledge precarious?','loose stones might shift','it was broad and secure','it was a prairie','Precarious means unsafe or likely to fail.'),Q(1,'Which situation is precarious?','standing on a crumbling ledge','sitting on a stable bench','walking on a dry level path','The adjective describes danger and instability.'),Q(1,'Choose a close synonym for precarious.','unstable','certain','comfortable','Precarious means not safe or secure.'),Q(1,'What might happen on a precarious ledge?','it could collapse','it could mail a letter','it could become a pottery wheel','The example warns that the loose stones could give way.')]);
P('precaution','From French precaution and Latin praecautio “guarding beforehand,” based on praecavere “beware in advance.”',[C('precaution.s1','safety','As a precaution, the crew shut off the gas before repairing the stove.','作为预防措施，工作人员在修理炉灶前关闭了燃气。','as a precaution','as-phrase','A precaution is an advance action taken to prevent harm.'),C('precaution.s2','attitude','She approached the unfamiliar trail with caution and a healthy precaution.','面对陌生小径，她保持谨慎和适度防备。','with precaution','with-phrase','Precaution can also refer to care taken to avoid risk.')],M('The crew took a precaution against fire by leaving the gas valve open during repairs.','The crew took a precaution against fire by closing the gas valve.','A precaution is a step taken to reduce risk.','meaning'),[Q(1,'What did the crew do as a precaution?','shut off the gas','light the stove','open every window only','A precaution is an advance safety action.'),Q(2,'How did she approach the unfamiliar trail?','carefully to avoid risk','without looking where she walked','after mailing a postcard','The second sense emphasizes cautious care.'),Q(1,'Which is a precaution?','wearing a helmet before cycling','waiting until after a fall to buy one','ignoring a warning','A precaution is taken ahead of time to prevent harm.'),Q(2,'What does precaution express in “with precaution”?','careful awareness of risk','certainty that nothing can go wrong','a religious sermon','It means acting cautiously.')]);
P('precautionary','From precaution + adjective suffix -ary; it describes an action intended to prevent harm before it occurs.',C('precautionary.s1','public safety','The agency issued a precautionary warning while engineers tested the dam’s sensors.','工程师测试水坝传感器期间，机构发布了预防性警告。','precautionary warning','adjective before noun','Precautionary means intended as advance prevention rather than repair after harm.'),M('The agency issued a precautionary warning only after the dam had already collapsed.','The agency issued a precautionary warning before damage occurred.','A precautionary action is meant to prevent harm in advance.','meaning'),[Q(1,'Why did the agency issue the warning?','to guard against possible danger','to report damage after collapse','to advertise a postcard','Precautionary actions aim to prevent harm before it happens.'),Q(1,'What were engineers testing?','the dam’s sensors','a pottery wheel','a power unit','The example specifies the sensors.'),Q(1,'Which phrase is precautionary?','a warning issued before a risk develops','a repair made after the damage','a report on an old event','The adjective means intended as advance protection.'),Q(1,'What does precautionary modify?','warning','agency','engineers','It is an adjective before the noun warning.')]);
P('precautious','From precaution + -ous, forming an adjective for someone wary and careful about possible danger.',C('precautious.s1','behavior','The precautious hikers checked the weather and marked a safe return route before setting out.','谨慎的徒步者出发前查看天气，并标好了安全返程路线。','precautious hikers','adjective before noun','Precautious describes a wary, risk-conscious person.'),M('The precautious hikers ignored the storm warning and left without a map.','The precautious hikers checked the forecast and prepared a return route.','A precautious person takes care to avoid possible danger.','meaning'),[Q(1,'What did the hikers do before setting out?','checked weather and planned a safe return','ignored the forecast','left their map behind','Precautious describes wary, careful behavior.'),Q(1,'Which group is precautious?','travelers who prepare for likely risks','travelers who dismiss every warning','travelers who walk blindfolded','The adjective means cautious about possible danger.'),Q(1,'What does precautious relate to?','taking precautions','writing a postscript','making pottery','It describes someone who acts carefully to avoid risk.'),Q(1,'Choose a close meaning for precautious.','wary','careless','reckless','Precautious means alert and careful.')]);
P('precede','From Latin praecedere “go before,” formed from prae “before” + cedere “go.”',[C('precede.s1','sequence','A short safety briefing will precede the laboratory demonstration.','实验室演示前会先进行简短的安全说明。','briefing will precede','verb + object','This sense means happen earlier in time or order.'),C('precede.s2','procession','Two guides preceded the visitors along the narrow cave passage.','两名向导走在访客前面，带他们穿过狭窄的洞道。','guides preceded the visitors','verb + object','The verb can mean go in front of people in a line.')],M('The safety briefing will precede the demonstration by happening after it is finished.','The safety briefing will precede the demonstration by happening first.','Precede means come before in time or order.','meaning'),[Q(1,'When will the briefing occur?','before the demonstration','after it finishes','only during cleanup','Precede means happen earlier.'),Q(2,'Where did the guides walk?','in front of the visitors','behind them at the end','inside a postal box','Precede can mean go in front of people.'),Q(1,'Which event precedes a lecture?','an introduction given before it','a summary written after it','a follow-up next year','The verb marks an earlier event.'),Q(2,'What did the guides do in the cave?','led the visitors from the front','walked behind the group','stayed at the entrance','The second sense means go in front of others.')]);
P('precedence','From Latin praecedentia, based on praecedere “go before”; it names the right or priority to come before others.',C('precedence.s1','rules','Emergency repairs take precedence over routine repainting when the budget is limited.','预算有限时，紧急维修优先于日常重新粉刷。','take precedence over','fixed verb phrase','Precedence means priority because something is more important.'),M('Emergency repairs take precedence over routine painting, so the crew paints first and ignores the repairs.','Emergency repairs take precedence, so the crew handles them before routine painting.','Taking precedence means receiving priority and being dealt with first.','meaning'),[Q(1,'What takes priority?','emergency repairs','routine repainting','a poster','Precedence is the right to be dealt with first.'),Q(1,'When does this priority matter?','when the budget is limited','when no work is needed','after every wall is painted','The example frames a choice between urgent and routine work.'),Q(1,'Which phrase means priority over another matter?','take precedence over','pounce at','postdate into','Take precedence over is the usual phrase.'),Q(1,'Why do repairs take precedence?','they are more important and urgent','they are decorative','they happened after painting','Precedence follows relative importance.')]);
P('precedent','From Latin praecedentem “going before,” from praecedere; it is an earlier case or decision used as a guide.',[C('precedent.s1','law','The judge cited a precedent from a similar case when explaining the ruling.','法官解释裁决时援引了一个类似案件的先例。','cited a precedent','verb + object','A precedent is an earlier decision guiding a later one.'),C('precedent.s2','custom','With no written rule, the team followed the precedent of rotating the chair each month.','没有书面规定时，团队沿用每月轮换主席的惯例。','followed the precedent','verb + object','Precedent can refer to an established custom.')],M('The judge cited a precedent from a future case that had not yet happened.','The judge cited an earlier precedent from a similar case.','A precedent is an earlier case or event, not a future one.','meaning'),[Q(1,'What did the judge cite?','an earlier similar case','a future decision','a postal notice','A legal precedent is an earlier decision used as a guide.'),Q(2,'What did the team do without a written rule?','followed an established rotation custom','waited for a court case','stopped choosing a chair','Precedent can mean a customary practice.'),Q(1,'Why is a case a precedent?','it can guide later decisions','it happens after every decision','it is a cooking measure','The word names an earlier event taken as a model.'),Q(2,'Which phrase uses the custom sense?','There is a precedent for rotating the chair.','The precedent was appealed in court.','The judge cited the precedent.','The first sentence refers to an established practice.')]);
P('preceding','From precede + -ing, used as an adjective for something coming earlier in time or order.',C('preceding.s1','documents','Please read the preceding paragraph before answering the question about the chart.','回答有关图表的问题前，请先阅读前一段。','preceding paragraph','adjective before noun','Preceding means coming before in time or sequence.'),M('The preceding paragraph appears after the paragraph it introduces.','The preceding paragraph appears before the paragraph it introduces.','Preceding means coming before, not after.','meaning'),[Q(1,'Which paragraph should readers read first?','the one before the current paragraph','the one written next year','the chart’s caption only','Preceding means earlier in the text.'),Q(1,'What does preceding modify?','paragraph','question','chart','The adjective appears before paragraph.'),Q(1,'Which event is preceding?','a briefing held before a demonstration','a review held after a demonstration','a simultaneous event','Preceding refers to earlier time or order.'),Q(1,'Choose a close synonym for preceding.','previous','following','unrelated','Preceding means coming before.')]);

})();
